package com.wizzadrds.theworldremembers.inventory; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; class NpcInventoryTest{@Test void failedRemovalDoesNotMutate(){var i=new NpcInventory();i.add("minecraft:diamond",2);assertFalse(i.remove("minecraft:diamond",3));assertEquals(2,i.count("minecraft:diamond"));} @Test void mainItemIdentityIsPreserved(){var i=new NpcInventory();i.add("minecraft:diamond",1);assertEquals("minecraft:diamond",i.items().get(0).itemId());}}
